package uz.mirix.tracelens.internal;
import org.springframework.http.HttpRequest;import org.springframework.http.client.*;import uz.mirix.tracelens.*;import java.io.IOException;import java.util.*;
public final class TraceLensClientHttpRequestInterceptor implements ClientHttpRequestInterceptor {private final TraceLensProperties p;public TraceLensClientHttpRequestInterceptor(TraceLensProperties p){this.p=p;}public ClientHttpResponse intercept(HttpRequest request,byte[] body,ClientHttpRequestExecution execution)throws IOException{TraceContext c=TraceContextHolder.current();if(c==null||!p.getHttpClient().isEnabled())return execution.execute(request,body);long started=System.nanoTime();ClientHttpResponse response=null;Throwable failure=null;try{response=execution.execute(request,body);return response;}catch(IOException|RuntimeException ex){failure=ex;throw ex;}finally{Map<String,String>a=new HashMap<>();if(response!=null)try{a.put("status",Integer.toString(response.getStatusCode().value()));}catch(IOException ignored){}if(failure!=null)a.put("error",failure.getClass().getSimpleName());c.record(TraceCategory.HTTP,HttpClientSupport.label(request.getMethod().name(),request.getURI(),p),started,System.nanoTime(),a);}}}
